/**
 * @suppress
 */
public object FfiConverterTypeMeshEventListener: FfiConverter<MeshEventListener, Long> {
    internal val handleMap = UniffiHandleMap<MeshEventListener>()

    override fun lower(value: MeshEventListener): Long {
        if (value is MeshEventListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): MeshEventListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return MeshEventListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): MeshEventListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MeshEventListener) = 8UL

    override fun write(value: MeshEventListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


