/**
 * The running mesh. Start one, keep it, stop it when the app is done with it.
 */
public interface MeshHandleInterface {
    
    /**
     * Whether this node is a light member. Always true for the app's embedded node.
     */
    fun `isLight`(): kotlin.Boolean
    
    /**
     * True while the endpoint is up.
     */
    fun `isRunning`(): kotlin.Boolean
    
    /**
     * Join a group from an invite code.
     *
     * Succeeds even when nobody answers — see [`JoinResult::via`].
     */
    fun `joinGroup`(`invite`: kotlin.String): JoinResult
    
    /**
     * Leave a group. Returns false if this node was not a member.
     */
    fun `leaveGroup`(`id`: kotlin.String): kotlin.Boolean
    
    /**
     * Every group this node belongs to, with member and online counts.
     */
    fun `listGroups`(): List<GroupInfo>
    
    /**
     * The members of one group, or of every group when `group` is `None`.
     */
    fun `listPeers`(`group`: kotlin.String?): List<PeerInfo>
    
    /**
     * The loopback port the `/stream` rewrite targets. Stays readable after `stop()`.
     */
    fun `localPort`(): kotlin.UShort
    
    /**
     * This device's node id: 64-character lowercase hex, the same encoding the `/stream` URL and
     * the gossip records use.
     */
    fun `nodeId`(): kotlin.String
    
    /**
     * Install (or, with `None`, remove) the event listener.
     *
     * One listener at a time: the app has exactly one place that fans these out to React, and a
     * list would only invite leaks across a reload.
     */
    fun `setListener`(`listener`: MeshEventListener?)
    
    /**
     * A snapshot of the node: id, port, relay in use and how peers are reached.
     */
    fun `status`(): MeshStatus
    
    /**
     * Close the endpoint and stop the loopback API. Idempotent.
     *
     * Everything is dropped: groups live in `mesh.db`, so a later `start` on the same data
     * directory comes back with the same node id and the same memberships.
     */
    fun `stop`()
    
    companion object
}

/**
 * The running mesh. Start one, keep it, stop it when the app is done with it.
 */
open class MeshHandle: Disposable, AutoCloseable, MeshHandleInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_stingstream_mesh_ffi_fn_free_meshhandle(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_stingstream_mesh_ffi_fn_clone_meshhandle(handle, status)
        }
    }

    
    /**
     * Whether this node is a light member. Always true for the app's embedded node.
     */override fun `isLight`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_is_light(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * True while the endpoint is up.
     */override fun `isRunning`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_is_running(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Join a group from an invite code.
     *
     * Succeeds even when nobody answers — see [`JoinResult::via`].
     */
    @Throws(MeshException::class)override fun `joinGroup`(`invite`: kotlin.String): JoinResult {
            return FfiConverterTypeJoinResult.lift(
    callWithHandle {
    uniffiRustCallWithError(MeshException) { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_join_group(
        it,
        
        FfiConverterString.lower(`invite`),_status)
}
    }
    )
    }
    

    
    /**
     * Leave a group. Returns false if this node was not a member.
     */
    @Throws(MeshException::class)override fun `leaveGroup`(`id`: kotlin.String): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCallWithError(MeshException) { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_leave_group(
        it,
        
        FfiConverterString.lower(`id`),_status)
}
    }
    )
    }
    

    
    /**
     * Every group this node belongs to, with member and online counts.
     */
    @Throws(MeshException::class)override fun `listGroups`(): List<GroupInfo> {
            return FfiConverterSequenceTypeGroupInfo.lift(
    callWithHandle {
    uniffiRustCallWithError(MeshException) { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_list_groups(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The members of one group, or of every group when `group` is `None`.
     */
    @Throws(MeshException::class)override fun `listPeers`(`group`: kotlin.String?): List<PeerInfo> {
            return FfiConverterSequenceTypePeerInfo.lift(
    callWithHandle {
    uniffiRustCallWithError(MeshException) { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_list_peers(
        it,
        
        FfiConverterOptionalString.lower(`group`),_status)
}
    }
    )
    }
    

    
    /**
     * The loopback port the `/stream` rewrite targets. Stays readable after `stop()`.
     */override fun `localPort`(): kotlin.UShort {
            return FfiConverterUShort.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_local_port(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * This device's node id: 64-character lowercase hex, the same encoding the `/stream` URL and
     * the gossip records use.
     */override fun `nodeId`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_node_id(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Install (or, with `None`, remove) the event listener.
     *
     * One listener at a time: the app has exactly one place that fans these out to React, and a
     * list would only invite leaks across a reload.
     */override fun `setListener`(`listener`: MeshEventListener?)
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_set_listener(
        it,
        
        FfiConverterOptionalTypeMeshEventListener.lower(`listener`),_status)
}
    }
    
    

    
    /**
     * A snapshot of the node: id, port, relay in use and how peers are reached.
     */
    @Throws(MeshException::class)override fun `status`(): MeshStatus {
            return FfiConverterTypeMeshStatus.lift(
    callWithHandle {
    uniffiRustCallWithError(MeshException) { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_status(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Close the endpoint and stop the loopback API. Idempotent.
     *
     * Everything is dropped: groups live in `mesh.db`, so a later `start` on the same data
     * directory comes back with the same node id and the same memberships.
     */override fun `stop`()
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_method_meshhandle_stop(
        it,
        _status)
}
    }
    
    

    

    


    
    companion object {
        
    /**
     * Start the endpoint and the loopback API.
     *
     * `data_dir` holds `node.key` and `mesh.db` and must be private to the app — on Android that
     * is `context.filesDir`, never external storage: the node key is the device's identity in
     * every group it has joined.
     *
     * `config_json` is [`MeshConfigInput`]; an empty string means "all defaults", which is a
     * light node on an ephemeral port with n0 discovery on and the DHT off.
     */
    @Throws(MeshException::class) fun `start`(`dataDir`: kotlin.String, `configJson`: kotlin.String): MeshHandle {
            return FfiConverterTypeMeshHandle.lift(
    uniffiRustCallWithError(MeshException) { _status ->
    UniffiLib.uniffi_stingstream_mesh_ffi_fn_constructor_meshhandle_start(
    
        
        FfiConverterString.lower(`dataDir`),
        FfiConverterString.lower(`configJson`),_status)
}
    )
    }
    

        
    }
    
}


/**
 * @suppress
 */
public object FfiConverterTypeMeshHandle: FfiConverter<MeshHandle, Long> {
    override fun lower(value: MeshHandle): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): MeshHandle {
        return MeshHandle(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): MeshHandle {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MeshHandle) = 8UL

    override fun write(value: MeshHandle, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



