/**
 * Everything that can go wrong, flattened to a message.
 *
 * The mesh's own errors carry a context chain (`{e:#}`) that names the failing step, and that
 * string is far more useful in a bug report than a variant would be — so the variants here
 * separate only the cases the *app* branches on.
 */
sealed class MeshException(message: String): kotlin.Exception(message) {
        
    /**
     * The handle has been stopped, or was never started.
     */
        class NotRunning(message: String) : MeshException(message)
        
    /**
     * The invite code is malformed, or of a version this build does not understand.
     */
        class BadInvite(message: String) : MeshException(message)
        
    /**
     * The configuration JSON did not parse.
     */
        class BadConfig(message: String) : MeshException(message)
        
    /**
     * Anything else, with the mesh's own context chain.
     */
        class Failed(message: String) : MeshException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MeshException> {
        override fun lift(error_buf: RustBuffer.ByValue): MeshException = FfiConverterTypeMeshError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeMeshError : FfiConverterRustBuffer<MeshException> {
    override fun read(buf: ByteBuffer): MeshException {
        
            return when(buf.getInt()) {
            1 -> MeshException.NotRunning(FfiConverterString.read(buf))
            2 -> MeshException.BadInvite(FfiConverterString.read(buf))
            3 -> MeshException.BadConfig(FfiConverterString.read(buf))
            4 -> MeshException.Failed(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: MeshException): ULong {
        return 4UL
    }

    override fun write(value: MeshException, buf: ByteBuffer) {
        when(value) {
            is MeshException.NotRunning -> {
                buf.putInt(1)
                Unit
            }
            is MeshException.BadInvite -> {
                buf.putInt(2)
                Unit
            }
            is MeshException.BadConfig -> {
                buf.putInt(3)
                Unit
            }
            is MeshException.Failed -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




